export const OTC_SOURCE = "// Phil OTC desk: a two-party token swap through an escrow desk.\n//\n// The maker locks tokens with the desk and names a price. The taker either\n// pays that price or walks away. Tokens and payment are linear values, so the\n// desk cannot keep, copy or lose either one: every path must hand each coin\n// to exactly one owner.\n\nrecord Token mode linear {\n  amount : U64\n}\n\nrecord Cash mode linear {\n  amount : U64\n}\n\n// Splitting the payment into the maker's proceeds and the desk fee.\n// The fee is in basis points (100 = 1%) and can never exceed 10%, so the\n// cut is always smaller than the payment and the multiplication cannot overflow.\ncallable TakeFee(payment : Cash, fee_bps : U64) -> (Cash, Cash) {\n  requires fee_bps <= 1000;\n  requires payment.amount <= 1000000000000;\n  outcomes { success (Cash, Cash) };\n}\n\nfn take_fee(payment : Cash, fee_bps : U64) -> (Cash, Cash) satisfies TakeFee {\n  let Cash { amount = total } = payment;\n  let cut = total * fee_bps / 10000;\n  return (construct Cash { amount = total - cut }, construct Cash { amount = cut });\n}\n\n// The desk only settles a payment that matches the asking price exactly.\ncallable Settle(payment : Cash, price : U64) -> Cash {\n  requires payment.amount == price;\n  outcomes { success Cash };\n}\n\nfn settle(payment : Cash, price : U64) -> Cash satisfies Settle {\n  return payment;\n}\n\ncallable Pay(wallet : Cash, price : U64) -> (Cash, Cash) {\n  requires price <= wallet.amount;\n  outcomes { success (Cash, Cash) };\n}\n\nfn pay(wallet : Cash, price : U64) -> (Cash, Cash) satisfies Pay {\n  let Cash { amount = total } = wallet;\n  return (construct Cash { amount = price }, construct Cash { amount = total - price });\n}\n\n// Maker and desk: lock the tokens, then learn how it ended.\nprotocol Listing {\n  role Maker = send (price : U64) then send (tokens : Token) then offer {\n    Filled => receive (proceeds : Cash) then end Sold |\n    Refunded => receive (tokens : Token) then end Returned\n  };\n  role Desk = receive (price : U64) then receive (tokens : Token) then select {\n    Filled => send (proceeds : Cash) then end Sold |\n    Refunded => send (tokens : Token) then end Returned\n  };\n}\n\n// Desk and taker: quote the deal, then swap or part ways.\nprotocol Deal {\n  role Desk = send (size : U64) then send (price : U64) then offer {\n    Accept => receive (payment : Cash) then send (tokens : Token) then end Swapped |\n    Decline => end Declined\n  };\n  role Taker = receive (size : U64) then receive (price : U64) then select {\n    Accept => send (payment : Cash) then receive (tokens : Token) then end Swapped |\n    Decline => end Declined\n  };\n}\n\ncomponent Maker(desk : Maker[Listing], selling : U64, price : {v : U64 | v <= 1000000000000}) provides U64 {\n  let quoted = send price on desk;\n  let locked = send construct Token { amount = selling } on quoted;\n  offer locked {\n    Filled => {\n      let (done, proceeds) = receive Cash on locked;\n      close done;\n      let Cash { amount = got } = proceeds;\n      console_write(\"maker sold for\", got);\n      return got;\n    }\n    Refunded => {\n      let (done, tokens) = receive Token on locked;\n      close done;\n      let Token { amount = back } = tokens;\n      console_write(\"maker got tokens back:\", back);\n      return convert 0 to U64;\n    }\n  };\n}\n\ncomponent Taker(desk : Taker[Deal], wallet : U64) provides U64 {\n  let (e1, size) = receive U64 on desk;\n  let (e2, price) = receive U64 on e1;\n  let funds = construct Cash { amount = wallet };\n  if ge(wallet, price) {\n    let (payment, change) = pay(funds, price);\n    let accepted = select Accept on e2;\n    let paid = send payment on accepted;\n    let (done, tokens) = receive Token on paid;\n    close done;\n    let Token { amount = got } = tokens;\n    let Cash { amount = left } = change;\n    console_write(\"taker bought\", got, \"and has\", left, \"left\");\n    return got;\n  } else {\n    let declined = select Decline on e2;\n    close declined;\n    let Cash { amount = left } = funds;\n    console_write(\"taker declined and keeps\", left);\n    return convert 0 to U64;\n  };\n}\n\ncomponent Desk(maker : Desk[Listing], taker : Desk[Deal], fee_bps : {v : U64 | v <= 1000}) provides U64 {\n  let (m1, price) = receive U64 on maker;\n  let (m2, tokens) = receive Token on m1;\n  let size = borrow tokens as t { return t.amount; };\n  let t1 = send size on taker;\n  let t2 = send price on t1;\n  offer t2 {\n    Accept => {\n      let (t3, payment) = receive Cash on t2;\n      let checked = settle(payment, price);\n      let (proceeds, cut) = take_fee(checked, fee_bps);\n      let t4 = send tokens on t3;\n      close t4;\n      let m3 = select Filled on m2;\n      let m4 = send proceeds on m3;\n      close m4;\n      let Cash { amount = kept } = cut;\n      console_write(\"desk fee\", kept);\n      return kept;\n    }\n    Decline => {\n      close t2;\n      let m3 = select Refunded on m2;\n      let m4 = send tokens on m3;\n      close m4;\n      return convert 0 to U64;\n    }\n  };\n}\n\narchitecture OtcDesk {\n  instance maker = Maker;\n  instance taker = Taker;\n  instance desk = Desk;\n  process maker_run = maker;\n  process taker_run = taker;\n  process desk_run = desk;\n  protocol listing = Listing;\n  protocol deal = Deal;\n  role listing.Maker = maker;\n  role listing.Desk = desk;\n  role deal.Desk = desk;\n  role deal.Taker = taker;\n  entry selling : U64;\n  entry price : U64;\n  entry wallet : U64;\n  entry fee_bps : U64;\n  bind maker.desk = listing.Maker;\n  bind maker.selling = selling;\n  bind maker.price = price;\n  bind taker.desk = deal.Taker;\n  bind taker.wallet = wallet;\n  bind desk.maker = listing.Desk;\n  bind desk.taker = deal.Desk;\n  bind desk.fee_bps = fee_bps;\n}\n\nprogram main = instantiate OtcDesk;\n";
